def find_array(u, v):
    if u > v or (u % 2 != v % 2):
        return "-1"
    if u == v:
        if u == 0:
            return "0"
        else:
            return "1\n{}".format(u)
    x = (v - u) // 2
    if u & x:
        return "3\n{} {} {}".format(x, x, u ^ x)
    else:
        return "2\n{} {}".format(x + u, x)

# Read input
u, v = map(int, input().split())

# Print output
print(find_array(u, v))
